INSERT INTO `diseases_veg` VALUES (1,'Фітофтороз','Грибкове захворювання, яке вражає листя, стебла і плоди рослин, особливо томатів та картоплі. На листках з\'являються темні плями, що швидко поширюються, призводячи до загибелі рослини.','Видалення уражених рослин. Обприскування фунгіцидами (наприклад, препаратами на основі мідного купоросу). Дотримання сівозміни та уникнення надмірного зволоження.'),(2,'Борошниста роса','Грибкове захворювання, що проявляється у вигляді білого порошкоподібного нальоту на листках, стеблах і плодах. Вражені ділянки втрачають здатність до фотосинтезу, листя скручується і всихає.','Обробка рослин сірчаними препаратами або спеціальними фунгіцидами. Уникнення густих посадок та забезпечення хорошої вентиляції.'),(3,'Коренева гниль','Захворювання, яке вражає кореневу систему рослин, спричиняючи її гниття. Коріння стає темним, рослина в\'яне, зупиняється у рості та часто гине. Захворювання поширюється у вологих умовах.','Поліпшення дренажу ґрунту, щоб уникнути застою води. Використання біофунгіцидів. Дотримання сівозміни.'),(4,'Антракноз','Грибкове захворювання, яке часто вражає кавуни та дині. На листках та плодах з\'являються темно-коричневі або чорні плями. Плоди можуть розтріскуватися, а тканини під плямами гниють.','Обприскування рослин мідьвмісними препаратами. Видалення уражених плодів і листя. Дотримання сівозміни.'),(5,'Мозаїка','Вірусне захворювання, що вражає листя рослин. Листя покривається мозаїчними світло-зеленими та жовтими плямами, рослина деформується і втрачає врожайність.','Видалення заражених рослин. Боротьба зі шкідниками (попелицями, трипсами), які переносять вірус. Використання стійких сортів.'),(6,'Фузаріоз','Грибкове захворювання, яке вражає судинну систему рослин. Листя жовтіє, скручується і в\'яне. Рослина швидко втрачає життєздатність і гине. Найчастіше вражає дині та кавуни.','Використання фунгіцидів. Дотримання сівозміни. Видалення та спалювання уражених рослин.'),(7,'Бактеріальна плямистість','Бактеріальне захворювання, що проявляється у вигляді дрібних, водянистих плям на листках і плодах. З часом плями темнішають і стають некротичними.','Використання бактеріальних препаратів. Видалення уражених частин рослин. Дотримання сівозміни.'),(8,'Сіра гниль','Грибкове захворювання, що вражає плоди, листя та стебла. Уражені ділянки вкриваються сірим пухнастим нальотом. Захворювання активно розвивається у вологих умовах.','Обробка фунгіцидами. Поліпшення вентиляції. Уникнення надмірного поливу. Видалення заражених рослин.');
/*!40000 ALTER TABLE `diseases_veg` ENABLE KEYS */;
UNLOCK TABLES;

