INSERT INTO `sorts_veg` VALUES (1,'Морква Паризький ринок','Оранжевий','70 - 75 днів ','30-50 г','Сорт використовується як для консервування, так і для вживання у свіжому вигляді.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-parijskiy-rynok-semena2.jpg?1734963120','Плоди відрізняються своєю незвичайною округлою формою і маленькими розмірами (2-4 см в діаметрі). М\'якоть яскраво-помаранчева, шкірка тонка і практично непомітна.',1),(2,'Морква амстердамська','Оранжевий','75 - 85 днів ','100-200 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-stolovaya-amsterdamskaya-semena_1.jpg?1734963840','серцевина маленька, м\'якоть ніжна, соковита',1),(3,'Морква Нантес Скарлет','Оранжевий','70 - 80 днів','80-120 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-nantes-skarlet_1.jpg?1734964200','Плоди моркви виростають довжиною до 18 см. Для них властивий гарний помаранчевий колір і відмінний товарний вигляд. Сорт високоврожайний і стійкий до утворення стрілок',1),(4,'Морква Абако F1','Оранжевий','80 - 85 днів ','100-225 г','Сорт придатний для комерційного виробництва, тривалого зберігання, переробки на дитячі соки, пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-abako-f1_1.jpg?1734964560','Плоди виростають помірно великі до 16 см, забарвлення м\'якоті темно-помаранчева, внутрішня частина - з червонуватим відтінком через високий вміст каротину',1),(5,'Морква Артек','помаранчево-червоний','65 - 85 днів ','80 - 130 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-artek_1.jpg?1734964560','Плоди цього сорту відрізняються соковитістю і відмінним смаком.',1),(6,'Морква оленка','Оранжевий','85 - 100 днів ','80 - 110 г','Сорт використовується для вживання у свіжому вигляді','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-alenka_1.jpg?1734964920','Відрізняється високою врожайністю і стійкістю до хвороб і низьких температур. Серединка у плодів виражена слабко.',1),(7,'Морква каріні','Оранжевий','90 - 100 днів ','100 - 150 г','Рекомендовані для вживання у свіжому вигляді, приготування дієтичного та дитячого харчування, віджимання соку, а також інших видів кулінарної переробки.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-karini_1.jpg?1734964920','Коренеплоди насичено-помаранчеві, циліндричні, тупоносі, соковиті і солодкі.',1),(8,'Морква лагуна F1','Оранжевий','80 - 85 днів ','100 - 130 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-laguna-f1_1.jpg?1734964920','Коренеплоди довжиною 17 - 20 см. Форма циліндрична, рівна, витягнута. Колір м\'якоті: інтенсивно-оранжевий. Серцевина дуже маленька.',1),(9,'Морква сімейний сад F1','Оранжевий','80 - 90 днів ','100 - 200 г','Можна вирощувати як в комерційних цілях, так і для домашнього вжитку. Підходить для вживання дітям - у свіжому вигляді й у якості соків або пюре.','https://ua.s.bekhost.com/uploads/catalog_products/tmp_500/morkov-semeynyy-sad-f1_1.jpg?1734965280','Плоди середні - довжиною до 16 см. Серединка помаранчево-червона, що свідчить про високий вміст каротину.',1),(10,'Берлікумер','Оранжевий','110 - 130 днів ','120 - 190 г','Використовують вживання в свіжому вигляді, переробки, консервування та заморозки. ','https://images.prom.ua/4135985376_nasinnya-morkvi-berlikumer.jpg','Коренеплід довгий, циліндричний з тупим кінчиком. Серцевина помаранчева. Придатний для тривалого зберігання. При зберіганні вміст каротину збільшується у 1,5 разу. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.',2),(11,'Морква вітамінна 6','Оранжевий','100 - 120 днів ','60 - 160 г','Рекомендований для вживання у свіжому вигляді та для зимового зберігання.','https://images.prom.ua/4134542814_nasinnya-morkvi-vitaminna.jpg','Коренеплід помаранчевий, циліндричний, тупокінцевий, довжиною 15 см, майже повністю занурений у ґрунт. М\'якуш оранжево червоний, соковитий, солодкий. Вимагає зрошення та розпушування ґрунту. Культура вимоглива до вологи та родючих, пухких ґрунтів. Смакові якості коренеплодів добрі.   Висівати у вологий ґрунт на глибину 2-3 см.',2),(12,'Морква каротель','оранжево-червоний','83 - 105 днів ','80 г','Цей сорт рекомендується для споживання у свіжому вигляді, а також для переробки в соки та пюре.','https://images.prom.ua/4139867104_nasinnya-morkvi-karotel.jpg','Коренеплід довжиною 10-12 см, насичено оранжево-червоного кольору, тупокінцевий. М\'якуш соковитий, дуже солодкий, хрумкий. Серед середньоранніх сортів відрізняється лежкістю коренеплодів та збереженням у них вітамінів. Висівати у вологий ґрунт на глибину 2-3 см.',2),(13,'Морква ласуня','червоно-жовтогарячий','80 - 104 днів ','60 - 155 г','Призначений для використання у свіжому вигляді, переробки, зберігання.','https://images.prom.ua/4164461134_nasinnya-morkvi-lasunya.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 20 см.  Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 15-16°С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.',2),(14,'Морква лосиноострівська','червоно-жовтогарячий','100 - 110 днів ','70 - 150 г','Сорт використовується для вживання у свіжому вигляді','https://images.prom.ua/4164472132_nasinnya-morkvi-losinoostrivska.jpg','Коренеплід циліндричний, інтенсивного червоно-жовтогарячого кольору, соковита, солодка, довжиною 15-25см. Один із найкращих столових сортів. Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів насіння рекомендується змочувати у воді кімнатної температури на добу, потім просушувати при температурі 15-16°С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.',2),(15,'Морква Шантане','оранжево-червоний','100 днів ','80 - 150 г','Сорт використовується для вживання у свіжому вигляді та зберігання','https://images.prom.ua/4133437242_nasinnya-morkvi-shantane.jpg','Коренеплід конічної форми, довжиною 14 см, оранжево-червоний, повністю занурений у ґрунт. Серцевина маленька. М\'якуш соковитий, яскраво-оранжевого кольору з високим вмістом цукру та каротину. Найкращий сорт для зимового зберігання. Культура вимоглива до вологи та родючих пухких ґрунтів. Сорт жаростійкий, стійкий до цвітіння та розтріскування. Висівати у вологий ґрунт на глибину 2-3 см.',2),(16,'Морква червоний велетень','оранжево-червоний','140 - 160 днів ','200 г','Підходить для приготування соку, придатні для тривалого зберігання.','https://images.prom.ua/4136091983_nasinnya-morkvi-chervonij.jpg','Коренеплоди конічні, довжиною 22-26 см. Серцевина невелика. М\'якуш червоно-оранжевий, дуже смачний, солодкий і соковитий. Сорт холодостійкий, невибагливий, стійкий до цвітіння та розтріскування коренеплодів. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.',3),(17,'Морква флакке','оранжево-червоний','110 - 130 днів','60 - 180 г','Використовують для тривалого зберігання, переробки та вживання у свіжому вигляді.','https://images.prom.ua/4164399087_nasinnya-morkvi-flakke.jpg','Коренеплоди тупоконічні, насиченого оранжево-червоного кольору, довжиною 20-25 см, вирівняні, гарна лежкість, відмінний смак, зовні привабливі. М\'якуш оранжево-червоний. Для відкритого ґрунту. Культура вимоглива до вологи та родючих пухких ґрунтів. Для отримання дружних сходів рекомендується змочувати насіння у воді кімнатної температури на добу, потім просушувати при температурі 15-16С до сипучості. Висівати у вологий ґрунт на глибину 2-3 см.',3),(18,'Морква флайові','яскраво-жовтогарячий','155 - 175 днів ','150 - 200 г','Рекомендується для вживання у свіжому вигляді, переробки та зберігання.','https://images.prom.ua/4133480440_nasinnya-morkvi-flajovi.jpg','Коренеплоди циліндричні, довжиною до 25 см. М\'якуш яскраво-жовтогарячий, соковитий, солодкий. Цінність сорту: висока врожайність, вирівняність та чудові смакові якості коренеплодів. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см.',3),(19,'Морква віта лонга','Оранжевий','100 - 110 днів ','95 - 130 г','Рекомендується для свіжого споживання та зберігання.','https://images.prom.ua/4136113676_nasinnya-morkvi-vita.jpg','Бадилля потужне. Коренеплід довгий – 25 см, товстої, конічної форми. Поверхня злегка ребриста, забарвлення м\'якоті та серцевини помаранчеве. Головка плоска, трохи виступає над поверхнею грунту, озеленена. Смакові властивості моркви Віта Лонга високі. ',3),(20,'Морква карлена','Оранжевий','150 днів ','80 - 150 г','Сорт придатний для споживання у свіжому вигляді, переробки та тривалого зберігання.','https://images.prom.ua/4134643784_nasinnya-morkvi-karlena.jpg','Коренеплід довгий, конічної форми, з тупим кінчиком. Забарвлення коренеплоду помаранчеве, серцевина невелика та середнього розміру, помаранчевого забарвлення. Смакові якості добрі. Цінність сорту: висока врожайність, вирівняність коренеплодів та їх хороші смакові якості. Культура вимоглива до вологи та родючих пухких ґрунтів. Висівати у вологий ґрунт на глибину 2-3 см. ',3),(21,'СІР F1 / SIR F1 - Капуста Білоголова, Clause','зелений','60 днів ','1,5 - 2 кг','Чудово підійде для використання у свіжому вигляді та квашення завдяки своєму солодкому і ніжному смаку','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/f/i/file_2_5.webp','Урожайний сильнорослий гібрид білокачанної капусти, голівки правильної округлої форми, тверді. Листя щільне міцне з восковим нашаруванням. Коренева система сильно розвинена. Характеризується високими якостями транспортування і нетривалим терміном зберігання без втрати товарності. Не схильний до розтріскування, висока стійкість до фузаріозу, завдяки високому польовому здоров\'ю. Висока стійкість до кліматичних умов вирощування в тому числі до різких понижень температури і нестачі вологи. Гарне польове збереження. Придатний до вирощування на важких за механічним складом ґрунтах.',4),(22,'ЕКСПРЕСС / EXPRESS — Капуста Білоголова, Hortus','зелений','75-80 днів ','1 - 1,2 кг','Для отримання раннього врожаю','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/6/7/6759_pic.webp','Плоди захищені восковим покриттям. Головки формуються світло-зеленого кольору, в розрізі білі.',4),(23,'ЄТМА F1 / JETMA F1 - Капуста Білоголова, Rijk Zwaan','зелений','45-50 днів ','0,7 - 1,5 кг','Найбільш вдалий в сфері використання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/j/e/jetma-rz-f1-1.webp','Голівка щільна, компактна, округла, красивого світло-зеленого кольору.',4),(24,'ЕЛІЗА F1 / ELIZA F1 – Капуста Білокочанна, Sakata','зелений','43-48 днів ','0,6 -1,2 кг','Для отримання надранньої продукції!','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/7/1/71680576_2843517995699142_5232195023310684160_o.webp','пристосований до різних умов і термінів вирощування. Довго зберігається в полі, що не характерно для інших ранніх гібридів. Переносить короткочасні заморозки. Для отримання надранньої продукції рекомендується висаджувати під укриття (теплиці, плівка, агроволокно). Сорт капусти Еліза характеризується наявністю злегка піднятої розетки. Листя невеликого розміру має хвилястий край і пухирчасту поверхню. Воно формує щільний качан округлої форми (може бути злегка жовтуватим всередині). У кожній голівці є невеликий качан. Приємний солодкуватий смак. Невибагливість у догляді (завдяки стійкості до несприятливих погодних умов, шкідників). Щоб отримати рясний урожай, насіння висаджувати слід уже на початку березня. При цьому капусту вирощують переважно розсадним методом. Якщо сіяти насіння в ґрунт, рекомендується вибирати схему 60х40 см і починати у другій половині травня. Варто пам\'ятати про використання комплексних добрив, регулярний полив та догляд.',4),(25,'ПАНДІОН F1 / PANDION F1 -Капуста Білокачанна, Seminis','зелений','48-53 днів','1-2 кг','Для споживання в свіжому вигляді.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/p/a/pandion_obr.webp','Качани округлі і щільні, ніжного зеленого забарвлення, внутрішня структура з тонкими листям і короткою кочергою, дуже довго не розтріскується. відрізняється чудовим збереженням в польових умовах і вирівняними за формою і розміром качанами. Стійкий до розтріскування і до судинного бактеріозу. Рекомендується для вирощування в плівкових теплицях і у відкритому ґрунті для отримання надранньої продукції.',4),(26,'СЛАВА / SLAVA — Капуста Білоголова, Hortus','зелений','110-115 днів.','4,5 кг','Сорт призначений для короткочасного зберігання (впродовж 3 місяців); для свіжого вигляду і квашення.','https://agrolife.ua/media/mf_webp/jpeg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/1/5/153643-0.webp','Головки округлі і плоско-округлі, щільні. Внутрішній качан середнього розміру. Сорт середньостійкий до основних хвороб і стійкий до розтріскування.',5),(27,'ГЛОРІЯ F1 / GLORIA F1 - Капуста Білокачанна, Syngenta','зелений','75-80 днів.','2–5 кг','Рання реалізація у свіжому вигляді і зберігання до 4 місяців.','https://agrolife.ua/media/mf_webp/jpg/media/catalog/product/cache/16b8c61ece3e3dc6c80fc300e1915d10/8/f/8f15b447e0b23ddc9d61d5116969b9ae.webp','Гібрид Глорія F1 адаптований до різних кліматичних зон, стійкий до фузаріозу. Не вимагає інтенсивного живлення. Можливий прямий посів у відкритий ґрунт. Унікальний за призначенням гібрид з можливістю посіву в два терміни: ранній посів — на річну реалізацію, пізній посів — на зберігання. Зберігає відмінні товарні якості весь період збир