CREATE TABLE `vegetables` (
  `idVeg` int NOT NULL AUTO_INCREMENT,
  `Name` varchar(150) DEFAULT NULL,
  `Type` varchar(45) DEFAULT NULL,
  `Protein_content` varchar(45) DEFAULT NULL,
  `Fat_сontent` varchar(45) DEFAULT NULL,
  `Carb_content` varchar(45) DEFAULT NULL,
  `Vitamins` mediumtext CHARACTER SET cp1251 COLLATE cp1251_general_ci,
  `Minerals` mediumtext,
  `Plant_time` mediumtext,
  `Compatibility` mediumtext,
  `Incompatibility` mediumtext,
  `Image` mediumtext,
  PRIMARY KEY (`idVeg`),
  UNIQUE KEY `idVeg_UNIQUE` (`idVeg`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
